"""Generate the bilingual GitHub homepage from the two standalone guides."""

import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render_homepage():
    english = (ROOT / "README.en.md").read_text(encoding="utf-8").strip()
    chinese = (ROOT / "README.zh-CN.md").read_text(encoding="utf-8").strip()
    english = english.replace("(README.zh-CN.md)", "(#user-content-chinese)")
    chinese = chinese.replace("(README.en.md)", "(#user-content-english)")
    return (
        "<!-- Generated by scripts/SyncReadme.py; edit the standalone guides. -->\n\n"
        '<details name="readme-language" open>\n'
        "<summary><strong>English</strong></summary>\n\n"
        '<a name="english"></a>\n\n'
        + english
        + '\n\n</details>\n\n<details name="readme-language">\n'
        + "<summary><strong>简体中文</strong></summary>\n\n"
        + '<a name="chinese"></a>\n\n'
        + chinese
        + "\n\n</details>\n"
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    homepage = ROOT / "README.md"
    expected = render_homepage()
    if args.check:
        matches = homepage.read_text(encoding="utf-8") == expected
        print("PASS README sync" if matches else "FAIL README is out of sync")
        return 0 if matches else 1
    homepage.write_text(expected, encoding="utf-8")
    print("Generated README.md (English open, Chinese collapsed)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
